// iOS recovery renderer: no Skia imports, image filters or GPU canvas setup.
import { memo } from 'react';
import { Image, Pressable, StyleSheet, Text, View } from 'react-native';
import Animated, { useAnimatedStyle, type SharedValue } from 'react-native-reanimated';
import type { MapCamera, MapSize } from '@breadcrumb/shared';
import { mapAssetInfo, mapAssets } from '@/generated/map-assets';
import { mapTileOpacity, type MapTile } from '@/lib/map-tiles';
import { mapImagePlacement, TILE_IMAGE_SIZE } from '@/lib/map-image-layout';
import type { MapLight } from '@/lib/map-appearance';
import { TileCache } from '@/lib/tile-cache';
import { useMapTiles } from '@/lib/use-map-tiles';

const cache = new TileCache<number>(async key => {
  const asset = mapAssets[key];
  const source = Image.resolveAssetSource(asset);
  if (!source?.uri) throw new Error('Missing campus tile');
  if (!await Image.prefetch(source.uri)) throw new Error('Could not load campus tile');
  return asset;
});

const CampusImage = memo(function CampusImage({ asset, tile, live, size }: {
  asset: number; tile: MapTile; live: SharedValue<MapCamera>; size: MapSize;
}) {
  const style = useAnimatedStyle(() => {
    const camera = live.get();
    const position = mapImagePlacement(tile, camera, size);
    return {
      opacity: mapTileOpacity(tile.level, camera, size),
      transform: [{ translateX: position.x }, { translateY: position.y }, { scale: position.scale }],
    };
  }, [tile, live, size.width, size.height]);
  return <Animated.Image source={asset} resizeMode="stretch" fadeDuration={0}
    accessible={false} style={[styles.tile, style]}/>;
});

export const CampusTiles = memo(function CampusTiles({ scene, size, live, light }: {
  scene: MapCamera; size: MapSize; live: SharedValue<MapCamera>; light: MapLight;
}) {
  const { tiles, failed, retry } = useMapTiles(cache, scene, size, mapAssetInfo.maxLevel);
  return <View pointerEvents="box-none" style={[StyleSheet.absoluteFill, styles.viewport]}>
    <View pointerEvents="none" importantForAccessibility="no-hide-descendants" accessibilityElementsHidden style={StyleSheet.absoluteFill}>
      {tiles.map(({ key, value, tile }) => <CampusImage key={key} asset={value} tile={tile} live={live} size={size}/>)}
      <View style={[StyleSheet.absoluteFill, { backgroundColor: '#102232', opacity: light.night * .58 + light.dusk * .18 }]}/>
    </View>
    {failed && <Pressable accessibilityRole="button" accessibilityLabel="Retry campus map" onPress={retry} style={styles.retry}>
      <Text>Map could not load. Tap to retry.</Text>
    </Pressable>}
  </View>;
});
const styles = StyleSheet.create({
  viewport: { overflow: 'hidden' },
  tile: { position: 'absolute', top: 0, left: 0, width: TILE_IMAGE_SIZE, height: TILE_IMAGE_SIZE, transformOrigin: [0, 0, 0] },
  retry: { position: 'absolute', top: 160, alignSelf: 'center', padding: 16, backgroundColor: '#FFFCF5', borderRadius: 12 },
});
