import type { MapCamera, MapSize } from '@breadcrumb/shared';
import { TILE_BLEED, TILE_PIXELS, type MapTile } from './map-tiles';

export const TILE_IMAGE_SIZE = TILE_PIXELS + TILE_BLEED * 2;

// Keep UIImage views at their bitmap dimensions. Only their compositor
// transform changes during gestures, avoiding image decoding on every frame.
export function mapImagePlacement(tile: MapTile, camera: MapCamera, size: MapSize) {
  'worklet';
  const pad = tile.span * TILE_BLEED / TILE_PIXELS;
  const left = tile.left - pad, top = tile.top - pad;
  const scale = Math.max(size.width, size.height) * camera.zoom / 320;
  return {
    x: size.width / 2 + (left - camera.x) * scale,
    y: size.height / 2 + (top - camera.y) * scale,
    scale: (tile.span + 2 * pad) * scale / TILE_IMAGE_SIZE,
  };
}

